import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';

const EMBRYO_DISCLOSURE = {
  status: 'conceptual_diagram_only' as const,
  summary:
    'Delivered with chronological Carnegie-stage / gestational-week summaries, germ-layer lineage maps, and clinical correlations. Staged 3D Carnegie embryonic meshes are not included in the current adult BodyParts3D dataset.',
  missingAssets: ['Licensed staged 3D human embryo meshes (Carnegie Stages 1–23)'],
};

function makeEmbryoChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  timelineStage: string,
  summary: string,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'embryology',
    chapterCode: `D${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['secondary_premed', 'medical_foundations', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_ncp_bio_9_12', gradeOrYear: 'Grade XII', unitOrModule: `Human Reproduction & Development (${chapterTitle})`, status: 'elective' },
      { frameworkId: 'in_cbse_bio_11_12', gradeOrYear: 'Class XII (Unit VI)', unitOrModule: 'Human Reproduction & Embryonic Development', status: 'elective' },
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 1–2', unitOrModule: `General & Systemic Embryology (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'anat_soc_core', gradeOrYear: 'BS / Graduate', unitOrModule: `Morphogenesis & Teratology (${timelineStage})`, status: 'recommended' },
    ],
    prerequisites: ['Mitosis and meiotic reduction division (B7)', 'Fundamental anatomical axes (dorsal/ventral, cranial/caudal)'],
    learningObjectives: [
      `Locate ${chapterTitle.toLowerCase()} accurately along the human developmental timeline (${timelineStage}).`,
      `Explain the morphogenetic cell movements, tissue inductions, and derivatives governing ${chapterTitle.toLowerCase()}.`,
      `Connect focal developmental disruptions in ${chapterTitle.toLowerCase()} to classic congenital anomalies and teratogenic windows.`,
    ],
    depthExplanations: {
      secondary_premed: `${summary} During ${timelineStage}, coordinated cell division, migration, and folding transform simpler embryonic sheets into specialized organ precursors.`,
      medical_foundations: `${mechanisms.join(' ')} Developmental window: ${timelineStage}. Clinically, ${clinical}`,
      graduate_research: `Spatiotemporal gene regulatory networks (Nodal, BMP4, FGF8, Shh, Wnt, and collinear Hox clusters) during ${timelineStage} drive epithelial–mesenchymal transition, left–right nodal ciliary breaking, and lineage fate restriction.`,
    },
    keyConcepts: [
      { term: 'Developmental Stage & Timing', definition: timelineStage },
      { term: 'Core Morphogenetic Event', definition: summary },
      { term: 'Congenital Anomaly Correlation', definition: clinical },
    ],
    keyFacts: [
      `Primary Carnegie / Gestational Stage: ${timelineStage}.`,
      'Weeks 3–8 represent the classical embryonic period of major organogenesis and peak teratogenic vulnerability.',
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Fetal organs simply scale up from miniature preformed replicas.', correction: 'Mammalian embryogenesis proceeds via sequential epigenesis: inductive signalling turns pluripotency into distinct patterned sheets through folding and lumen remodelling.' },
      { misconception: 'First-trimester teratogen exposure stops damaging development after implantation completes.', correction: 'Major structural malformations peak during Weeks 3–8 organogenesis, while functional CNS maturation remains vulnerable through the fetal period.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} unfolds across ${timelineStage} via tightly timed tissue inductions and folding mechanics. Integrating these steps clarifies adult gross relations and congenital anomaly patterns.`,
    keyTakeaways: [
      `Timing: ${timelineStage}.`,
      mechanisms[0] ?? summary,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'human_anatomy', relation: 'Adult vascular trunks, mesenteries, and nerve courses retain direct traces of embryonic folding and migration.' },
      { domainId: 'molecular_genetics', relation: 'Transcription-factor mutations and chromosomal aneuploidies frequently present during this embryonic window.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['2d_diagram', 'structured_text'],
    diagram: {
      id: `diag-d${num}`,
      title: `${chapterTitle} — Developmental Sequence (${timelineStage})`,
      kind: 'pathway',
      caption: summary,
      disclaimer: 'Conceptual embryological timeline schematic; staged 3D Carnegie embryonic meshes are not included in the adult atlas.',
      nodes: [
        { id: 'n1', label: `Precursor State`, sublabel: timelineStage, tone: 'slate' },
        { id: 'n2', label: `Inductive / Folding Event`, sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'blue' },
        { id: 'n3', label: `Definitive Derivative`, sublabel: mechanisms[1]?.slice(0, 62) || clinical.slice(0, 62), tone: 'teal' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Paracrine induction & EMT' },
        { from: 'n2', to: 'n3', label: 'Lineage patterning & lumen closure' },
      ],
    },
    assetDisclosure: EMBRYO_DISCLOSURE,
    activity: {
      title: `Carnegie Timeline & Derivative Mapping (${chapterTitle})`,
      kind: 'interpretation',
      prompt: `Place ${chapterTitle} on the Weeks 1–38 timeline (${timelineStage}), list its primary precursor tissue and mature derivative, and predict the anatomical defect if folding or fusion fails.`,
      keyTakeaway: clinical,
    },
    readingKeys: ['ap_ch28_embryo', 'ncbi_mboc_alberts'],
    shortAnswers: [
      { id: `sa-d${num}-1`, prompt: `Specify the developmental window (${timelineStage}) and outline the key cellular or tissue transition during ${chapterTitle}.`, expectedPoints: mechanisms.slice(0, 2), modelAnswer: `${timelineStage}: ${mechanisms.join(' ')}`, level: 'medical_foundations' },
      { id: `sa-d${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB} in embryonic origin or developmental timing.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} compared with ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'secondary_premed' },
      { id: `sa-d${num}-3`, prompt: `Explain the embryonic mechanism behind a congenital disorder linked to ${chapterTitle}.`, expectedPoints: [clinical], modelAnswer: clinical, level: 'medical_foundations' },
    ],
    appliedCase: {
      id: `app-d${num}-1`,
      title: `Prenatal Counseling & Morphogenetic Correlation: ${chapterTitle}`,
      scenario: `During embryology teaching review (${timelineStage}), students analyze how disruption of ${chapterTitle.toLowerCase()} produces structural asymmetry or failure of midline closure.`,
      questions: ['Which precursor structure fails to remodel normally?', 'What is the timing window of highest developmental vulnerability?'],
      workedSolution: `Target stage: ${timelineStage}. Mechanistically: ${mechanisms[0]} Outcome: ${clinical}`,
      level: 'medical_foundations',
    },
    selfChecks: mcqs,
  };
}

